1	package httpapi
2	
3	import (
4		"crypto/hmac"
5		"crypto/rand"
6		"crypto/sha256"
7		"encoding/base64"
8		"encoding/hex"
9		"encoding/json"
10		"errors"
11		"maps"
12		"net/http"
13		"net/url"
14		"strconv"
15		"strings"
16		"time"
17	
18		"github.com/cocosolocoder/signalroom/internal/events"
19	)
20	
21	// Pagination defaults and bounds.
22	const (
23		defaultPageLimit = 100
24		maxPageLimit     = 1000
25		cursorVersion    = 1
26	)
27	
28	// CursorStore persists the per-directory signing key and query snapshots for
29	// one data directory. Cursors are only valid against the directory whose key
30	// signed them.
31	type CursorStore interface {
32		CursorKey() []byte
33		SaveSnapshot(id string, payload []byte) error
34		LoadSnapshot(id string) ([]byte, error)
35	}
36	
37	// pageResponse is the GET /events/page body. next_cursor is null when the
38	// snapshot has no more records.
39	type pageResponse struct {
40		Events     []eventDTO `json:"events"`
41		NextCursor *string    `json:"next_cursor"`
42	}
43	
44	// snapshotQuery is the normalized, comparable form of a page request's
45	// filters. Bounds are pointers so a missing end and the zero instant are
46	// distinguishable.
47	type snapshotQuery struct {
48		Service  string            `json:"service"`
49		Severity string            `json:"severity"`
50		Since    *time.Time        `json:"since,omitempty"`
51		Until    *time.Time        `json:"until,omitempty"`
52		Labels   map[string]string `json:"labels,omitempty"`
53	}
54	
55	func snapshotQueryFromQuery(q events.Query) snapshotQuery {
56		sq := snapshotQuery{
57			Service:  strings.TrimSpace(q.Service),
58			Severity: strings.ToLower(strings.TrimSpace(q.Severity)),
59			Labels:   q.Labels,
60		}
61		if !q.Since.IsZero() {
62			t := q.Since
63			sq.Since = &t
64		}
65		if !q.Until.IsZero() {
66			t := q.Until
67			sq.Until = &t
68		}
69		return sq
70	}
71	
72	// matches reports whether q, after the same normalization, is this filter
73	// set. Time zones and label order are irrelevant; severity case and
74	// surrounding whitespace are normalized away.
75	func (sq snapshotQuery) matches(q events.Query) bool {
76		if sq.Service != strings.TrimSpace(q.Service) {
77			return false
78		}
79		if sq.Severity != strings.ToLower(strings.TrimSpace(q.Severity)) {
80			return false
81		}
82		if !timePtrEqual(sq.Since, q.Since) || !timePtrEqual(sq.Until, q.Until) {
83			return false
84		}
85		return maps.Equal(sq.Labels, q.Labels)
86	}
87	
88	// equal compares two stored filter sets, used to cross-check a cursor
89	// against its snapshot.
90	func (sq snapshotQuery) equal(other snapshotQuery) bool {
91		if sq.Service != other.Service || sq.Severity != other.Severity {
92			return false
93		}
94		if !timePtrPtrEqual(sq.Since, other.Since) || !timePtrPtrEqual(sq.Until, other.Until) {
95			return false
96		}
97		return maps.Equal(sq.Labels, other.Labels)
98	}
99	
100	func timePtrEqual(p *time.Time, t time.Time) bool {
101		if p == nil {
102			return t.IsZero()
103		}
104		return !t.IsZero() && p.Equal(t)
105	}
106	
107	func timePtrPtrEqual(a, b *time.Time) bool {
108		if a == nil || b == nil {
109			return a == b
110		}
111		return a.Equal(*b)
112	}
113	
114	// snapshotPayload is the durable record of one first-page query: the ordered
115	// id set captured at that moment and the normalized filters that produced it.
116	type snapshotPayload struct {
117		IDs   []string      `json:"ids"`
118		Query snapshotQuery `json:"query"`
119	}
120	
121	// cursorPayload is the signed, opaque continuation token. It carries the
122	// snapshot id, the next offset, the filter set (cross-checked against the
123	// snapshot), and a fingerprint of the signing key so a cursor from another
124	// data directory is rejected even before the HMAC is considered.
125	type cursorPayload struct {
126		V int           `json:"v"`
127		S string        `json:"s"`
128		O int           `json:"o"`
129		Q snapshotQuery `json:"q"`
130		D string        `json:"d"`
131	}
132	
133	func fingerprint(key []byte) string {
134		sum := sha256.Sum256(key)
135		return base64.RawURLEncoding.EncodeToString(sum[:])
136	}
137	
138	func encodeCursor(cp cursorPayload, key []byte) string {
139		payload, _ := json.Marshal(cp)
140		mac := hmac.New(sha256.New, key)
141		mac.Write(payload)
142		return base64.RawURLEncoding.EncodeToString(payload) + "." +
143			base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
144	}
145	
146	func decodeCursor(encoded string, key []byte) (cursorPayload, error) {
147		parts := strings.Split(encoded, ".")
148		if len(parts) != 2 {
149			return cursorPayload{}, errors.New("invalid cursor")
150		}
151		payload, err := base64.RawURLEncoding.DecodeString(parts[0])
152		if err != nil {
153			return cursorPayload{}, errors.New("invalid cursor")
154		}
155		gotMAC, err := base64.RawURLEncoding.DecodeString(parts[1])
156		if err != nil {
157			return cursorPayload{}, errors.New("invalid cursor")
158		}
159		mac := hmac.New(sha256.New, key)
160		mac.Write(payload)
161		if !hmac.Equal(gotMAC, mac.Sum(nil)) {
162			return cursorPayload{}, errors.New("invalid cursor")
163		}
164		var cp cursorPayload
165		if err := json.Unmarshal(payload, &cp); err != nil {
166			return cursorPayload{}, errors.New("invalid cursor")
167		}
168		if cp.V != cursorVersion {
169			return cursorPayload{}, errors.New("invalid cursor")
170		}
171		return cp, nil
172	}
173	
174	// pageEvents serves GET /events/page. A request without a cursor starts a
175	// fresh snapshot; a request with one continues the snapshot it names, with
176	// the same filters and a possibly changed limit.
177	func (h *Handler) pageEvents(w http.ResponseWriter, r *http.Request) {
178		if r.Method != http.MethodGet {
179			w.Header().Set("Allow", "GET")
180			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
181			return
182		}
183		if h.unavailable() {
184			writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
185			return
186		}
187	
188		values := r.URL.Query()
189		key := h.cursors.CursorKey()
190	
191		var snap snapshotPayload
192		var snapshotID string
193		offset := 0
194	
195		cursorValues, hasCursor := values["cursor"]
