1	package events
2	
3	import (
4		"maps"
5		"sort"
6		"strings"
7		"sync"
8	)
9	
10	// BeforeCommit persists a batch of brand-new events. It runs while the
11	// timeline lock is held and before the batch becomes visible to queries, so a
12	// successful return guarantees the batch is durable and committed atomically.
13	// Returning an error rejects the batch without touching the timeline.
14	type BeforeCommit func(persisted []Event) error
15	
16	// Timeline is a concurrency-safe, de-duplicated event timeline that accepts
17	// whole batches and reports replays of already-stored events.
18	type Timeline struct {
19		mu     sync.RWMutex
20		byID   map[string]Event
21		events []Event
22	}
23	
24	// NewTimeline returns an empty timeline.
25	func NewTimeline() *Timeline {
26		return &Timeline{byID: make(map[string]Event)}
27	}
28	
29	// IngestResult counts how a batch was applied: Created events are new,
30	// Replayed events matched an existing event with the same id and content.
31	type IngestResult struct {
32		Created  int
33		Replayed int
34	}
35	
36	// Ingest normalizes and validates every event first, then checks the whole
37	// batch against existing events and itself. Validation failures produce a
38	// ValidationError; duplicate ids with differing content, or a repeated id
39	// within the batch, produce a ConflictError. Nothing is stored when an error
40	// is returned.
41	//
42	// New events are passed to beforeCommit for durable storage; only after it
43	// succeeds does the batch become visible, so concurrent readers see either
44	// the complete batch or none of it.
45	func (t *Timeline) Ingest(batch []Event, beforeCommit BeforeCommit) (IngestResult, error) {
46		normalized := make([]Event, len(batch))
47		for i, event := range batch {
48			norm, err := Normalize(event)
49			if err != nil {
50				return IngestResult{}, err
51			}
52			normalized[i] = norm
53		}
54	
55		t.mu.Lock()
56		defer t.mu.Unlock()
57	
58		pending := make(map[string]struct{}, len(normalized))
59		var created []Event
60		var result IngestResult
61		for _, event := range normalized {
62			if _, repeated := pending[event.ID]; repeated {
63				return IngestResult{}, &ConflictError{Reason: "event id repeats within batch"}
64			}
65			pending[event.ID] = struct{}{}
66			if existing, ok := t.byID[event.ID]; ok {
67				if !sameEvent(existing, event) {
68					return IngestResult{}, &ConflictError{Reason: "event id already exists with different content"}
69				}
70				result.Replayed++
71				continue
72			}
73			created = append(created, event)
74			result.Created++
75		}
76	
77		if len(created) > 0 {
78			if beforeCommit != nil {
79				if err := beforeCommit(created); err != nil {
80					return IngestResult{}, err
81				}
82			}
83			for _, event := range created {
84				t.byID[event.ID] = event
85				t.events = append(t.events, event)
86			}
87			sort.SliceStable(t.events, func(i, j int) bool {
88				return byTimeThenID(t.events[i], t.events[j])
89			})
90		}
91		return result, nil
92	}
93	
94	// Load inserts events recovered from durable storage during startup. Every
95	// event must already be normalized; a duplicate id with differing content is
96	// reported as a conflict so the caller can fail rather than mutate data.
97	func (t *Timeline) Load(event Event) error {
98		if _, err := Normalize(event); err != nil {
99			return err
100		}
101		t.mu.Lock()
102		defer t.mu.Unlock()
103		if existing, ok := t.byID[event.ID]; ok {
104			if !sameEvent(existing, event) {
105				return &ConflictError{Reason: "event id already exists with different content"}
106			}
107			return nil
108		}
109		t.byID[event.ID] = event
110		t.events = append(t.events, event)
111		return nil
112	}
113	
114	// SortAll orders recovered events by time, then id. Call it once after Load.
115	func (t *Timeline) SortAll() {
116		t.mu.Lock()
117		defer t.mu.Unlock()
118		sort.SliceStable(t.events, func(i, j int) bool {
119			return byTimeThenID(t.events[i], t.events[j])
120		})
121	}
122	
123	// Query returns the events matching the optional filters, ordered by time and
124	// then by id. Time equality uses absolute instants.
125	func (t *Timeline) Query(query Query) []Event {
126		service := strings.TrimSpace(query.Service)
127		severity := strings.ToLower(strings.TrimSpace(query.Severity))
128	
129		t.mu.RLock()
130		defer t.mu.RUnlock()
131		result := make([]Event, 0, len(t.events))
132		for _, event := range t.events {
133			if service != "" && event.Service != service {
134				continue
135			}
136			if severity != "" && event.Severity != severity {
137				continue
138			}
139			if !query.Since.IsZero() && event.At.Before(query.Since) {
140				continue
141			}
142			if !query.Until.IsZero() && event.At.After(query.Until) {
143				continue
144			}
145			if !labelsMatch(event.Labels, query.Labels) {
146				continue
147			}
148			result = append(result, event)
149		}
150		return result
151	}
152	
153	// SnapshotIDs returns the ids of events matching the optional filters, in
154	// time-then-id order. The set is taken under the timeline lock, so a batch
155	// committed concurrently is either fully present or fully absent; events
156	// added after the call never appear in the returned set, which makes it
157	// suitable for stable pagination across later writes.
158	func (t *Timeline) SnapshotIDs(query Query) []string {
159		service := strings.TrimSpace(query.Service)
160		severity := strings.ToLower(strings.TrimSpace(query.Severity))
161	
162		t.mu.RLock()
163		defer t.mu.RUnlock()
164		ids := make([]string, 0, len(t.events))
165		for _, event := range t.events {
166			if service != "" && event.Service != service {
