1	package httpapi
2	
3	import (
4		"net/http"
5		"net/http/httptest"
6		"net/url"
7		"testing"
8	)
9	
10	// page issues a GET /events/page request and returns the status and body.
11	func page(t *testing.T, server *httptest.Server, query string) (int, map[string]any) {
12		t.Helper()
13		resp, err := http.Get(server.URL + "/events/page" + query)
14		if err != nil {
15			t.Fatalf("page: %v", err)
16		}
17		defer resp.Body.Close()
18		return decode(t, resp)
19	}
20	
21	// pageEvents extracts the events array and next_cursor from a page response.
22	// A null next_cursor is returned as the empty string.
23	func pageEvents(t *testing.T, out map[string]any) ([]map[string]any, string) {
24		t.Helper()
25		raw, ok := out["events"].([]any)
26		if !ok {
27			t.Fatalf("events is not an array: %v", out)
28		}
29		events := make([]map[string]any, len(raw))
30		for i, e := range raw {
31			events[i] = e.(map[string]any)
32		}
33		var cursor string
34		if c, ok := out["next_cursor"].(string); ok {
35			cursor = c
36		}
37		return events, cursor
38	}
39	
40	func seedEvents(t *testing.T, server *httptest.Server, n int) {
41		t.Helper()
42		body := `{"events":[`
43		for i := 0; i < n; i++ {
44			if i > 0 {
45				body += ","
46			}
47			body += `{"id":"e` + itoa(i) + `","service":"s","severity":"info","message":"m","at":"2026-10-01T09:` + pad2(i) + `:00Z"}`
48		}
49		body += `]}`
50		if status, _ := post(t, server, body); status != http.StatusOK {
51			t.Fatalf("seed %d events: status %d", n, status)
52		}
53	}
54	
55	func itoa(n int) string {
56		if n == 0 {
57			return "0"
58		}
59		var b []byte
60		for n > 0 {
61			b = append([]byte{byte('0' + n%10)}, b...)
62			n /= 10
63		}
64		return string(b)
65	}
66	
67	func pad2(n int) string {
68		if n < 10 {
69			return "0" + itoa(n)
70		}
71		return itoa(n)
72	}
73	
74	func TestPageBasicPaging(t *testing.T) {
75		server, _, _ := newTestServer(t)
76		seedEvents(t, server, 5)
77	
78		// Page 1: limit 2.
79		status, out := page(t, server, "?limit=2")
80		if status != http.StatusOK {
81			t.Fatalf("page 1: %d %v", status, out)
82		}
83		events, cursor := pageEvents(t, out)
84		if len(events) != 2 || events[0]["id"] != "e0" || events[1]["id"] != "e1" {
85			t.Fatalf("page 1: %v", events)
86		}
87		if cursor == "" {
88			t.Fatal("page 1 should have a next_cursor")
89		}
90	
91		// Page 2.
92		status, out = page(t, server, "?limit=2&cursor="+cursor)
93		if status != http.StatusOK {
94			t.Fatalf("page 2: %d %v", status, out)
95		}
96		events, cursor = pageEvents(t, out)
97		if len(events) != 2 || events[0]["id"] != "e2" || events[1]["id"] != "e3" {
98			t.Fatalf("page 2: %v", events)
99		}
100		if cursor == "" {
101			t.Fatal("page 2 should have a next_cursor")
102		}
103	
104		// Page 3 (last, partial).
105		status, out = page(t, server, "?limit=2&cursor="+cursor)
106		if status != http.StatusOK {
107			t.Fatalf("page 3: %d %v", status, out)
108		}
109		events, cursor = pageEvents(t, out)
110		if len(events) != 1 || events[0]["id"] != "e4" {
111			t.Fatalf("page 3: %v", events)
112		}
113		if cursor != "" {
114			t.Fatalf("page 3 should have null next_cursor, got %q", cursor)
115		}
116	}
117	
118	func TestPageDefaultLimit(t *testing.T) {
119		server, _, _ := newTestServer(t)
120		seedEvents(t, server, 3)
121	
122		status, out := page(t, server, "")
123		if status != http.StatusOK {
124			t.Fatalf("status: %d %v", status, out)
125		}
126		events, cursor := pageEvents(t, out)
127		if len(events) != 3 {
128			t.Fatalf("default limit should return all 3, got %d", len(events))
129		}
130		if cursor != "" {
131			t.Fatal("no more records, next_cursor should be null")
132		}
133	}
134	
135	func TestPageLimitValidation(t *testing.T) {
136		server, _, _ := newTestServer(t)
137		for _, q := range []string{
138			"limit=0",
139			"limit=1001",
140			"limit=-1",
141			"limit=1.5",
142			"limit=abc",
143			"limit=",
144			"limit=1&limit=2",
145			"limit=%201",
146			"limit=100000000000000000000",
147		} {
148			status, out := page(t, server, "?"+q)
149			if status != http.StatusBadRequest {
150				t.Fatalf("%q: want 400, got %d %v", q, status, out)
151			}
152			if msg, _ := out["error"].(string); msg == "" {
153				t.Fatalf("%q: missing error string", q)
154			}
155		}
156	}
157	
158	func TestPageCursorValidation(t *testing.T) {
159		server, _, _ := newTestServer(t)
160		post(t, server, `{"events":[{"id":"e1","service":"s","severity":"info","message":"m","at":"2026-10-01T09:00:00Z"}]}`)
161	
162		for _, q := range []string{
163			"cursor=",
164			"cursor=not-a-cursor",
165			"cursor=aaa&cursor=bbb",
166			"cursor=eyJ2IjoxfQ.aaaa",
167		} {
168			status, out := page(t, server, "?"+q)
169			if status != http.StatusBadRequest {
170				t.Fatalf("%q: want 400, got %d %v", q, status, out)
171			}
172			if msg, _ := out["error"].(string); msg == "" {
173				t.Fatalf("%q: missing error string", q)
174			}
175		}
176	}
177	
178	func TestPageSnapshotStableAcrossWrites(t *testing.T) {
179		server, _, _ := newTestServer(t)
