	if len(events) != 2 || events[0]["id"] != "e2" || events[1]["id"] != "e3" {
		t.Fatalf("equivalent continuation must resume from e2: %v", events)
	}

	// Carrying an explicit until where the snapshot had none is likewise a
	// different condition.
	added := url.Values{}
